-12 text-center text-muted">Belum ada promo yang cocok.</td></tr>@endforelse</tbody></table></div><div class="border-t border-border px-4 py-3">{{ $promotions->links() }}</div></section>@if($createOpen)<div class="fixed inset-0 z-50 grid place-items-center bg-slate-900/40 p-4" role="dialog" aria-modal="true"><div class="w-full max-w-xl rounded-xl border border-border bg-surface p-6"><div class="flex justify-between"><div><p class="text-xs font-bold uppercase tracking-wider text-primary">Promo</p><h2 class="mt-1 text-xl font-black">Tambah promo</h2><p class="mt-1 text-sm text-muted">Field mengikuti tipe promo existing; kode dan usage limit belum tersedia di domain.</p></div><button wire:click="closeCreate" type="button" aria-label="Tutup" class="text-2xl text-muted">×</button></div><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="sm:col-span-2"><span class="nl-label">Store</span><select wire:model="storePublicId" class="nl-input w-full">@foreach($stores as $storeItem)<option value="{{ $storeItem->public_id }}">{{ $storeItem->name }}</option>@endforeach</select></label><label class="sm:col-span-2"><span class="nl-label">Nama promo</span><input wire:model="promotionName" class="nl-input w-full" placeholder="Promo akhir pekan"></label><label><span class="nl-label">Tipe</span><select wire:model="promotionType" class="nl-input w-full"><option value="percentage">Persentase</option><option value="fixed">Nominal</option><option value="fixed_price">Harga khusus</option></select></label><label><span class="nl-label">Nilai</span><input wire:model="promotionValue" type="number" min="0" class="nl-input w-full"></label><label class="sm:col-span-2"><span class="nl-label">Produk (opsional)</span><select wire:model="productPublicId" class="nl-input w-full"><option value="">Semua produk</option>@foreach($products as $product)<option value="{{ $product->public_id }}">{{ $product->name }} · {{ $product->sku }}</option>@endforeach</select></label><label><span class="nl-label">Mu